 if(faceSignature()!==faceVersion||id!==snapshotId()||wardrobe!==profile.cloudId)throw new Error('The wardrobe changed while preparing. Tap Continue again.');
 const storedSheets=await Promise.all(pack.manifest.map(async(sheet,i)=>({...sheet,image:await blobData(pack.files[i])})));
 if(faceSignature()!==faceVersion||id!==snapshotId()||wardrobe!==profile.cloudId)throw new Error('The wardrobe changed while preparing. Tap Continue again.');
 t.snapshotId=id;t.handoff={version:5,preparedAt:now(),catalog:catalogSnapshot(),photoAttachments:storedSheets,faceAttachments:facePack.manifest,returnAccess:{endpoint:cloudBase()+'/functions/v1/wardrobe-beta-handoff',token:Array.from(crypto.getRandomValues(new Uint8Array(32))).map(n=>n.toString(16).padStart(2,'0')).join(''),expiresAt:new Date(Date.now()+48*3600000).toISOString()},instructions:planningPrompt(t,id).replaceAll('attached','saved').replaceAll('Current-wardrobe.json','data.handoff.catalog')};t.updatedAt=now();
