 for(const o of tripOutfits(t).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)))){if(o.slot==='evening'||o.date===t.endDate||dates.has(o.date))continue;dates.add(o.date);const place=String(o.place||o.plan?.split(':')[0]||'').split(/→|->/).pop().split('/')[0].trim();if(place&&!/^(home|flight|airport)$/i.test(place))counts.set(place,(counts.get(place)||0)+1)}
