 const startDate=r.startDate,endDate=r.endDate,per=t.conversational?(r.outfitsPerDay||'one'):t.per;if(!['one','two'].includes(per))throw new Error('Invalid outfit frequency.');
 if(!Array.isArray(r.outfits)||!r.outfits.length||r.outfits.length>182)throw new Error('The plan needs daily outfits.');
 const allowed=new Set(activeItems().map(it=>it.id)),slots=new Set();
 for(const x of r.outfits){if(!validDate(x.date)||x.date<startDate||x.date>endDate)throw new Error('Invalid outfit date: '+x.date);const slot=x.slot||'day';if(!['day','evening'].includes(slot))throw new Error('Use day or evening slots.');const k=x.date+':'+slot;if(slots.has(k))throw new Error('Duplicate date/slot: '+k);slots.add(k);if(!Array.isArray(x.itemIds)||!x.itemIds.length)throw new Error('An outfit has no garments.');for(const id of x.itemIds)if(!allowed.has(id))throw new Error('Unknown or archived garment '+id+'. Nothing was imported. Correct the reply before saving.');if(new Set(x.itemIds).size!==x.itemIds.length)throw new Error('A garment is repeated within one outfit.');if(!String(x.scene||'').trim())throw new Error('Add a setting for every outfit.');}
 for(let d=new Date(startDate+'T12:00:00Z');d.toISOString().slice(0,10)<=endDate;d.setUTCDate(d.getUTCDate()+1)){const day=d.toISOString().slice(0,10);for(const slot of (per==='two'?['day','evening']:['day']))if(!slots.has(day+':'+slot))throw new Error('Missing '+slot+' outfit on '+day)}
 if(r.gaps!==undefined&&!Array.isArray(r.gaps))throw new Error('Shopping suggestions must be a list.');
