 if(r.optionalLooks!==undefined&&!Array.isArray(r.optionalLooks))throw new Error('Optional looks must be a list.');const optionalIds=new Set();
 for(const x of r.optionalLooks||[]){if(!x.id||x.id==='owned'||optionalIds.has(x.id))throw new Error('Invalid optional look ID.');optionalIds.add(x.id);if(x.date&&(x.date<r.startDate||x.date>r.endDate||!validDate(x.date)))throw new Error('Optional look date is outside this trip.');if(x.slot&&!['day','evening'].includes(x.slot))throw new Error('Invalid optional look slot.');if(!Array.isArray(x.itemIds)||x.itemIds.some(id=>!allowed.has(id))||new Set(x.itemIds).size!==x.itemIds.length)throw new Error('Optional look includes an unknown, repeated or archived garment.');if(!Array.isArray(x.productIds)||!x.productIds.length||x.productIds.some(id=>!productIds.has(id))||new Set(x.productIds).size!==x.productIds.length)throw new Error('Optional look needs exact recommended products.');if(!String(x.scene||'').trim())throw new Error('An optional look needs a setting.');}
