 out.innerHTML=`<h3>${esc(r.name||t.name)}</h3><p>${esc(r.summary||'')}</p><p>${esc(r.startDate)} – ${esc(r.endDate)}</p><p>${r.outfits.length} outfits · ${new Set(r.outfits.flatMap(x=>x.itemIds)).size} owned pieces · ${(r.renders||[]).length} renders.</p>${r.outfits.map(x=>`<div class="panel"><b>${esc(x.date)} ${esc(x.slot||'day')} · ${esc(x.name)}</b>${renderPhotos(lookRenders(r,x))}<p>${esc(x.note||'')}</p>${x.itemIds.map(id=>`<span style="display:inline-block;width:100px;vertical-align:top;margin:6px"><img src="${esc(thumbOf(itemById(id))||'')}" alt="${esc(id)}" style="width:90px;height:100px;object-fit:contain"><br>${esc(id+' '+itemById(id).name)}</span>`).join('')}</div>`).join('')}${productCards(r.gaps)}${optionalCards(r.optionalLooks,(r.gaps||[]).map(cleanProduct),r)}<p class="muted sm">${tripOutfits(t).length?'This replaces the journey’s outfit plan. Existing renders are retained only for unchanged outfits and settings.':'Save to create your daily lookbook.'}</p><button class="primary" id="savePlanFinal">${partial?((r.renders||[]).length?'Save available plan and images':'Save outfit plan'):'Save complete lookbook'}</button>`;
