pastePlan=async function(fromBox){try{let txt=$('#tp_paste').value;if(!fromBox){try{txt=await navigator.clipboard.readText();$('#tp_paste').value=txt}catch{throw new Error('Paste the reply into the box, then tap Review plan.')}}previewPlan(parseReply(txt));$('#planMsg').textContent='Review the daily outfits below before saving.'}catch(e){$('#planMsg').textContent=e.message}};
$('#pastePlanBtn').onclick=()=>pastePlan(false);$('#usePasteBtn').onclick=()=>pastePlan(true);$('#planFile').onchange=async e=>{try{$('#tp_paste').value=await e.target.files[0].text();await pastePlan(true)}catch(err){$('#planMsg').textContent=err.message}e.target.value=''};
applyPlan=async function(r){const original=validatePlan(r),t=structuredClone(original),old=tripOutfits(t),at=now();Object.assign(t,{startDate:r.startDate,endDate:r.endDate,per:r.outfitsPerDay||t.per||'one',name:String(r.name||t.name).slice(0,120),summary:String(r.summary||''),status:'planned',updatedAt:at,cover:cleanTripCover(r.cover)||t.cover||null,gaps:(r.gaps||[]).map(cleanProduct).filter(g=>g.item),optionalLooks:(r.optionalLooks||[]).map(x=>({...x,renders:lookRenders(r,x,x.id)}))});t.messages=[...(t.messages||[]),{role:'assistant',text:t.summary,at}];
 const os=r.outfits.map((x,i)=>{const prev=old.find(o=>o.date===x.date&&(o.slot||'day')===(x.slot||'day'));const same=prev&&JSON.stringify(prev.itemIds)===JSON.stringify(x.itemIds)&&prev.scene===x.scene;return {id:prev?.id||'outfit-'+rid(),tripId:t.id,trip:t.name,date:x.date,slot:x.slot||'day',name:[x.day||x.date,x.name].filter(Boolean).join(' · '),place:String(x.place||''),plan:[x.place,x.plan].filter(Boolean).join(': '),scene:String(x.scene),weather:String(x.weather||''),note:String(x.note||''),itemIds:x.itemIds,renders:lookRenders(r,x).length?lookRenders(r,x):(same?prev.renders||[]:[]),order:t.id+'-'+x.date+'-'+(x.slot==='evening'?'1':'0'),createdAt:prev?.createdAt||at,updatedAt:at}});
 const removed=old.filter(o=>!os.some(n=>n.id===o.id));await new Promise((ok,no)=>{const tr=db.transaction(['trips','outfits','meta'],'readwrite');tr.objectStore('trips').put(t);for(const o of os)tr.objectStore('outfits').put(o);for(const o of removed){tr.objectStore('outfits').delete(o.id);tr.objectStore('meta').put({id:'del:outfit:'+o.id,kind:'outfit',key:o.id,at})}tr.oncomplete=ok;tr.onerror=()=>no(tr.error);tr.onabort=()=>no(tr.error)});trips[trips.findIndex(x=>x.id===t.id)]=t;outfits=outfits.filter(o=>o.tripId!==t.id).concat(os);scheduleSync();resetJourney();renderTrips();openTrip(t.id);$('#planMsg').textContent='Plan saved.';
};
const oldOpenTrip=openTrip;
openTrip=function(id){oldOpenTrip(id);const t=allTrips().find(x=>x.id===id);if(!t)return;const os=tripOutfits(t),pack=[...new Set(os.flatMap(o=>o.itemIds))].map(itemById).filter(Boolean);const sheet=$('#sheet');
 if(!t.imported){sheet.querySelector('.shead').insertAdjacentHTML('afterend',`<div class="row"><button id="continueJourney">Continue planning</button></div>`);$('#continueJourney').onclick=()=>editJourney(t.id)}
 const panels=[...sheet.querySelectorAll('.panel')],packing=panels.find(p=>p.querySelector('.packing'));if(packing){packing.innerHTML=`<h3>Packing list · ${pack.length} pieces</h3>${pack.map(it=>`<label class="packrow"><input type="checkbox" data-packed="${esc(it.id)}" ${(t.packed||[]).includes(it.id)?'checked':''}><img src="${thumbOf(it)||''}" alt=""><span>${esc(it.id)} · ${esc(it.name)}${it.archived?' (archived)':''}</span></label>`).join('')}`;packing.onchange=async e=>{if(!e.target.dataset.packed||t.imported)return;const actual=trips.find(x=>x.id===t.id);const set=new Set(actual.packed||[]);e.target.checked?set.add(e.target.dataset.packed):set.delete(e.target.dataset.packed);actual.packed=[...set];actual.updatedAt=now();await putTrip(actual)}}
 const gaps=panels.find(p=>p.querySelector('.gaps'));if(gaps)gaps.innerHTML=productCards(t.gaps);
 if(t.optionalLooks?.length)sheet.insertAdjacentHTML('beforeend',optionalCards(t.optionalLooks,t.gaps));

 if(t.messages?.length)sheet.insertAdjacentHTML('beforeend',`<details><summary>Planning conversation</summary>${t.messages.map(m=>`<p><b>${m.role==='user'?'You':'Plan'}</b><br>${esc(m.text)}</p>`).join('')}</details>`);
};

// Never silently omit an outfit garment from a render handoff.
const oldBuildPrompt=buildPrompt;
buildPrompt=function(o){return strictRule+'\n\n'+oldBuildPrompt(o).replace('one or two photos per garment','all available photos per garment')+'\nIf any garment or face cannot be matched to its reference, ask instead of substituting. Use every supplied garment reference; do not infer details from memory.'};
function renderErrors(o){if(!faces.length)return 'Add your face photos in More first.';if(!o.itemIds?.length)return 'Choose the outfit pieces first.';for(const id of o.itemIds){const it=itemById(id);if(!it||it.archived)return 'Replace missing or archived garment '+id+' before rendering.';if(!it.photos?.length)return 'Add a reference photo for '+id+' before rendering.'}return ''}
prepGptFiles=async function(o){const error=renderErrors(o);if(error){gptPack={key:'',files:null,error};return}const ps=outfitPieces(o);const key=cyrb(JSON.stringify({o,faces:faces.map(f=>[f.id,f.updatedAt||f.addedAt]),pieces:ps.map(p=>[p.id,p.it.updatedAt,p.it.photos.length])}));if(gptPack.key===key&&gptPack.files)return;gptPack={key,files:null};try{const refs=faces.slice(0,3).map((f,i)=>({u:f.data,n:`face-${i+1}.jpg`}));for(const p of ps)(p.it.photos||[]).forEach((u,i)=>refs.push({u,n:`${p.id}-reference-${i+1}.jpg`}));const files=[new File([buildPrompt(o)],'Try-on-instructions.txt',{type:'text/plain'})];for(const r of refs){const b=await dataURLtoBlob(await shrink(r.u,1400));files.push(new File([b],r.n,{type:'image/jpeg'}))}if(gptPack.key===key)gptPack.files=files}catch(e){gptPack.error=e.message}};
tryOnInChatGPT=function(o){const out=$('#tryonMsg'),error=renderErrors(o);if(error){out.textContent=error;return}if(!gptPack.files){out.textContent=gptPack.error||'Preparing all face and garment references. Tap again in a moment.';prepGptFiles(o);return}handoffPanel(gptPack.files,out,`All references ready (${gptPack.files.length-1} photos). Use ChatGPT to generate the image, then return and tap Add picture. If its upload limit is reached, attach the remaining references in the next message before generating.`);out.querySelector('a[href="https://claude.ai/"]')?.remove()};
const oldRenderOutfit=renderOutfitView;
renderOutfitView=function(first){oldRenderOutfit(first);const o=outfits.find(x=>x.id===openOutfitId);if(!o)return;if(o.tripId){$('#sheet .shead').insertAdjacentHTML('afterend','<button class="small" id="backJourney">← Back to journey</button>');$('#backJourney').onclick=()=>{openOutfitId=null;openTrip(o.tripId)}}const err=renderErrors(o);if(err)$('#tryonMsg').textContent=err};
// Dates are evaluated at render time and on return from another app.
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&profile){if(tab==='trips')renderTrips();if(tab==='home')renderHome()}});
const style=document.createElement('style');style.textContent='.packrow{display:flex;align-items:center;gap:10px;padding:8px 0;margin:0}.packrow img{width:44px;height:52px;object-fit:contain;border-radius:6px}.packrow input{width:20px;height:20px}.packrow span{font-size:13px}.menu .mi{padding-left:0}#planReview{max-height:65vh;overflow:auto}#requestFiles .row a,#closetPack .row a{font-size:13px}';document.head.appendChild(style);

exportForChatGPT=async function(){const out=$('#moreMsg');out.textContent='Preparing your current wardrobe…';try{const files=await requestFiles(strictRule+'\nUse the attached catalog and photos to discuss my wardrobe. Do not plan from prior memory.');handoffPanel(files,out,'Current active wardrobe ready.')}catch(e){out.textContent=e.message}};

// Keep image bytes out of the trip JSON: small, resumable private reference rows.
function splitReferenceSheets(t){return (t.handoff.photoSheets||[]).map((text,sheet)=>{const hash=cyrb(text),chunks=[];for(let part=0,at=0;at<text.length;part++,at+=60000)chunks.push({id:`ref-${t.id}-${hash}-${sheet}-${part}`,data:{sheet,part,text:text.slice(at,at+60000)}});return {sheet,hash,chunks}})}
const normalToCloud=toCloud;
const normalFromCloud=fromCloud;
fromCloud=async function(kind,c,old){const x=await normalFromCloud(kind,c,old);if(kind==='trip'&&x.optionalLooks)x.optionalLooks=await Promise.all(x.optionalLooks.map(look=>normalFromCloud('outfit',look,old?.optionalLooks?.find(previous=>previous.id===look.id))));return x;};
toCloud=function(kind,x,uploads){if(kind==='trip'&&x.handoff?.photoSheets?.length)throw new Error('REFERENCE_PENDING');const c=normalToCloud(kind,x,uploads);if(kind==='trip'&&c.handoff?.photoAttachments){c.handoff={...c.handoff,photoAttachments:c.handoff.photoAttachments.map(sheet=>{if(!sheet.image?.startsWith('data:'))return {...sheet};const hash=photoHash(sheet.image);uploads.set(hash,sheet.image);return {...sheet,image:'sb:'+hash}})}}if(kind==='trip'&&c.optionalLooks)c.optionalLooks=c.optionalLooks.map(look=>normalToCloud('outfit',look,uploads));return c};
const normalPushWardrobe=pushWardrobe;
pushWardrobe=async function(d,cloudId,status){
 for(let pass=0;pass<10;pass++){
 for(const trip of await getAll('trips',d)){
  if(!trip.handoff?.photoSheets?.length)continue;
  const sheets=splitReferenceSheets(trip),rows=sheets.flatMap(s=>s.chunks);let done=0;
  for(const row of rows){const marker='reference-upload:'+row.id;
   if(!await dGet(d,'meta',marker)){status(`Saving photo references… ${done+1} of ${rows.length}`);await pushRows([{user_id:session.uid,wardrobe:cloudId,kind:'reference',id:row.id,data:row.data,deleted:false}]);await dPut(d,'meta',{id:marker,uploaded:true})}done++;
  }
  const latest=await dGet(d,'trips',trip.id);if(latest?.handoff?.preparedAt!==trip.handoff.preparedAt)continue;
  latest.handoff.photoReferences=sheets.map(s=>({sheet:s.sheet,hash:s.hash,chunkIds:s.chunks.map(c=>c.id)}));delete latest.handoff.photoSheets;latest.handoff.version=2;latest.updatedAt=now();await dPut(d,'trips',latest);
  if(d===db){const i=trips.findIndex(t=>t.id===latest.id);if(i>=0)trips[i]=latest}
 }
 try{return await normalPushWardrobe(d,cloudId,status)}catch(e){if(e.message!=='REFERENCE_PENDING')throw e}
 }throw new Error('The wardrobe kept changing during sync. Let the current save finish, then retry.');
};

// Swipe dismissal is restricted to empty draft journeys. Planned trips never opt in.
function canSwipeDraft(t){return t.status==='draft'&&tripOutfits(t).length===0&&!t.imported}
const allTripsIncludingDismissed=allTrips;
allTrips=function(){return allTripsIncludingDismissed().filter(t=>!t.dismissed)};
let draftSwipe=null,suppressTripClickUntil=0;
const tripListElement=$('#tripList');
tripListElement.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-swipe-draft]');if(!el||e.isPrimary===false)return;const t=trips.find(t=>t.id===el.dataset.trip);if(!t||!canSwipeDraft(t))return;draftSwipe={el,id:t.id,x:e.clientX,y:e.clientY,pointer:e.pointerId,dx:0}});
tripListElement.addEventListener('pointermove',e=>{const g=draftSwipe;if(!g||g.pointer!==e.pointerId)return;const dy=e.clientY-g.y;g.dx=e.clientX-g.x;if(Math.abs(dy)>30&&Math.abs(dy)>Math.abs(g.dx)){g.el.style.transform='';draftSwipe=null;return}if(g.dx< -12)g.el.style.transform=`translateX(${Math.max(g.dx,-150)}px)`});
tripListElement.addEventListener('pointercancel',()=>{if(draftSwipe)draftSwipe.el.style.transform='';draftSwipe=null});
tripListElement.addEventListener('pointerup',async e=>{const g=draftSwipe;draftSwipe=null;if(!g)return;g.el.style.transform='';if(g.dx> -85||Math.abs(e.clientY-g.y)>45)return;suppressTripClickUntil=Date.now()+700;const t=trips.find(t=>t.id===g.id);if(!t||!canSwipeDraft(t))return;try{const dismissed={...t,dismissed:true,updatedAt:now()};await putTrip(dismissed);Object.assign(t,dismissed);if(editingTrip===t.id)$('#newBrief').click();renderTrips();toast('Draft dismissed');const el=$('#toast');el.innerHTML='Draft dismissed <button class="link" id="undoDraft" style="color:inherit;margin-left:12px">Undo</button>';clearTimeout(el._h);el._h=setTimeout(()=>el.style.display='none',7000);$('#undoDraft').onclick=async()=>{t.dismissed=false;t.updatedAt=now();await putTrip(t);renderTrips();toast('Draft restored')}}catch(err){toast('Could not dismiss draft: '+err.message)}});
tripListElement.addEventListener('click',e=>{if(Date.now()<suppressTripClickUntil){e.preventDefault();e.stopImmediatePropagation()}},true);

// Cloud proposals are separate from trips, so a response cannot overwrite a
// user's draft or accepted outfits. The existing validator gates acceptance.
let checkingReturnedPlans=false,shownProposalKey='';
function renderMatchesPlan(plan,z){const variant=z.variant||'owned',look=variant==='owned'?(plan.outfits||[]).find(x=>x.date===z.date&&(x.slot||'day')===z.slot):(plan.optionalLooks||[]).find(x=>x.id===variant);return !!look&&JSON.stringify(look.itemIds)===JSON.stringify(z.itemIds)&&look.scene===z.scene&&JSON.stringify(look.productIds||[])===JSON.stringify(z.productIds||[]);}
function missingRenders(plan){return [...(plan.outfits||[]).map(x=>({look:x,variant:'owned'})),...(plan.optionalLooks||[]).map(x=>({look:x,variant:x.id}))].filter(({look,variant})=>!lookRenders(plan,look,variant).length);}
async function checkReturnedPlans(manual=false){
 if(checkingReturnedPlans||!session||!profile?.cloudId||!cloudReady())return;
 checkingReturnedPlans=true;
 try{
  const rows=await api('/rest/v1/records?select=id,data&kind=eq.proposal&deleted=eq.false&wardrobe=eq.'+encodeURIComponent(profile.cloudId))||[];
  const scoped=rows.filter(r=>r.data?.plan?.snapshotId===snapshotId()&&trips.some(t=>t.id===r.id&&!t.dismissed&&t.snapshotId===r.data.plan.snapshotId)&&(!manual||!editingTrip||r.id===editingTrip));
  const candidates=scoped.filter(r=>r.data.status!=='rendering').sort((a,b)=>String(b.data.updatedAt).localeCompare(String(a.data.updatedAt)));
  for(const row of candidates){
   const key=row.id+':'+row.data.updatedAt;
   if((await dGet(db,'meta','accepted-proposal:'+row.id))?.key===key)continue;
   if(!manual&&shownProposalKey===key)continue;
   const images=await api('/rest/v1/records?select=data&kind=eq.render&deleted=eq.false&wardrobe=eq.'+encodeURIComponent(profile.cloudId))||[];
   const plan={...row.data.plan,renders:images.map(x=>x.data).filter(z=>z.tripId===row.id&&z.snapshotId===row.data.plan.snapshotId&&renderMatchesPlan(row.data.plan,z))};
   try{validatePlan(plan)}catch(e){if(manual)throw e;continue}plan.renders=await Promise.all(plan.renders.map(async z=>{const image=z.image.startsWith('sb:')?await downloadPhoto(z.image.slice(3)):z.image;if(!image)throw new Error('A returned image could not be loaded. Try again.');return {...z,image};}));
   validatePlan(plan);const missing=missingRenders(plan);if(!manual&&(row.data.status==='partial'||missing.length))continue;plan.bundleStatus=row.data.status==='partial'||missing.length?'partial':'complete';shownProposalKey=key;editJourney(row.id);$('#replyDetails').open=true;previewPlan(plan);
   if(plan.bundleStatus==='partial')$('#planReview').insertAdjacentHTML('afterbegin','<p class="muted sm">'+esc(row.data.error||'Outfit plan received. '+missing.length+' try-on images have not returned yet.')+'</p>');
   const save=$('#savePlanFinal'),accept=save.onclick;
   save.onclick=async e=>{await accept(e);if(trips.find(t=>t.id===row.id)?.status==='planned'&&!$('#planReview').innerHTML)await dPut(db,'meta',{id:'accepted-proposal:'+row.id,key})};
   $('#planMsg').textContent=plan.bundleStatus==='partial'?'A partial result arrived. See what remains below.':'Your complete lookbook is ready. Review outfits, products and renders below.';return;
  }
  if(manual)$('#planMsg').textContent=scoped.some(r=>r.data.status==='rendering')?'An outfit plan arrived; its images have not all returned yet.':'No new proposal has arrived yet.';
 }catch(e){$('#planMsg').textContent='Could not load the returned plan: '+e.message}
 finally{checkingReturnedPlans=false}
}
const syncBeforeProposals=syncNow;
syncNow=async function(){await syncBeforeProposals();if(!syncing)await checkReturnedPlans()};
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkReturnedPlans()});


